export const MYDB_DEMO_FILE = { name: '서울여중 중1 9문항 표본.pdf', url: 'assets/mydb/seoulyeo-middle1-sample.pdf', dbId: 'school-225416', sha256: '17c97bac35a645ecc3c22204ece68483776912b62810552ad6180f9f057f5940' };
export async function matchesMyDBDemo(file) {
  if (!file || file.size > 20 * 1024 * 1024) return false;
  const digest = await globalThis.crypto.subtle.digest('SHA-256', await file.arrayBuffer());
  return [...new Uint8Array(digest)].map(b => b.toString(16).padStart(2, '0')).join('') === MYDB_DEMO_FILE.sha256;
}
