function loadWorkspace() {
  const fallback = { folders: [{id:'school',name:'내신 자료'},{id:'book',name:'교재 자료'},{id:'preparation',name:'수업 준비'}], assignments:{}, memos:{}, titles:{}, expanded:true };
  try {
    const v=JSON.parse(localStorage.getItem(WORKSPACE_KEY)||'null');
    if (!v || !Array.isArray(v.folders) || v.folders.some(f=>!f||typeof f.id!=='string'||typeof f.name!=='string')) return fallback;
    return {...fallback,...v,assignments:v.assignments&&typeof v.assignments==='object'?v.assignments:{},memos:v.memos&&typeof v.memos==='object'?v.memos:{}};
  } catch { return fallback; }
}
function getView(store) {
  if (!views.has(store)) views.set(store,{workspace:loadWorkspace(),scope:'all',route:'',folder:null,query:'',tab:'all',mode:'list',sort:'recent',folderSort:'custom',pro:false,lite:false,answer:false,solution:false,selected:new Set(),banner:8,detail:null,detailFilter:{unit:'',tag:'',min:1,max:9,answers:[],hideSolution:false},detailSelected:new Set()});
  return views.get(store);
}
function saveWorkspace(view,ui) {try{localStorage.setItem(WORKSPACE_KEY,JSON.stringify(view.workspace));}catch{ui.toast('이 브라우저에서 작업공간을 저장하지 못했습니다.');}}
