export function purchasedDBIds(state) {
  return Object.entries(state.dbRights||{}).filter(([,r])=>r&&(r.mode==='permanent'&&(r.all||(r.questionIds||[]).length>0)||(r.permanentQuestionIds||[]).length>0)).map(([id])=>id);
}
export function myDBStatus(db) {return /진행|작업|검수/.test(db.status||'')?'progress':'complete';}
function dbFolder(d,workspace) {return Object.hasOwn(workspace.assignments,d.id)?workspace.assignments[d.id]:d.kind==='book'?'book':'school';}
export function filterMyDBs(dbs, state, view) {
  const bought=new Set(purchasedDBIds(state)),query=String(view.query||'').normalize('NFKC').toLowerCase().replace(/\s/g,'');
  return dbs.filter(d=>{
    if(view.scope==='purchased'&&!bought.has(d.id))return false;
    if(['review','payment'].includes(view.scope))return false;
    const status=myDBStatus(d);
    if(['progress','complete'].includes(view.scope)&&status!==view.scope)return false;
    if(view.tab&&view.tab!=='all'&&status!==view.tab)return false;
    if(view.folder&&dbFolder(d,view.workspace)!==view.folder)return false;
    if(query&&!`${view.workspace.titles?.[d.id]||d.title} ${view.workspace.memos[d.id]||''}`.normalize('NFKC').toLowerCase().replace(/\s/g,'').includes(query))return false;
    const lite=/lite|라이트/i.test(d.format||'');
    if((view.pro||view.lite)&&!(view.pro&&!lite||view.lite&&lite))return false;
    if(view.answer&&!/정답/.test(d.explanation||''))return false;
    if(view.solution&&(!/해설/.test(d.explanation||'')||/없음|미확인/.test(d.explanation||'')))return false;
    return true;
  }).sort((a,b)=>view.sort==='name'?a.title.localeCompare(b.title,'ko'):view.sort==='old'?Number(a.year)-Number(b.year):Number(b.year)-Number(a.year));
}
