    const save=e=>{e.preventDefault();const name=modal.querySelector('input').value.trim();if(!name)return toast('폴더 이름을 입력해 주세요.');if(folder)folder.name=name;else view.workspace.folders.push({id:'folder-'+crypto.randomUUID(),name});saveWorkspace(view,ctx.ui);closeModal();redraw();};
