function popupMenu(anchor,items) {
  document.querySelector('.mdb-popover')?.remove();
  const pop=document.createElement('div');pop.className='mdb-popover';pop.setAttribute('role','menu');
  for(const item of items){const b=document.createElement('button');b.type='button';b.disabled=!!item.disabled;b.setAttribute('role','menuitem');b.textContent=item.label;if(item.hint){const hint=document.createElement('small');hint.textContent=item.hint;b.append(hint);}b.onclick=()=>{pop.remove();document.removeEventListener('pointerdown',close);item.action?.();};pop.append(b);}
  document.body.append(pop);const r=anchor.getBoundingClientRect();pop.style.left=Math.min(r.right-190,innerWidth-204)+'px';pop.style.top=Math.min(r.bottom+4,innerHeight-pop.offsetHeight-12)+'px';pop.querySelector('button:not(:disabled)')?.focus();
  const close=e=>{if(!pop.contains(e.target)&&!anchor.contains(e.target)){pop.remove();document.removeEventListener('pointerdown',close);}};document.addEventListener('pointerdown',close);pop.onkeydown=e=>{if(e.key==='Escape'){pop.remove();anchor.focus();document.removeEventListener('pointerdown',close);}};
}
